pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _newOwner) public {
        address ownerBefore = c.owner();
        try c.setOwner(_newOwner) {
            // call succeeded
        } catch {
            // call reverted
        }
        address ownerAfter = c.owner();
        assertTrue(ownerAfter == ownerBefore, "Owner should not change after setOwner call");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _owner) public {
        vm.assume(_owner != address(0));
        bool success;
        try c.setOwner(_owner) {
            success = true;
        } catch {
            success = false;
        }
        assertTrue(!success || c.owner() == _owner);
    }
}
